package main

import (
	"context"
	"fmt"
	"os"

	"github.com/urfave/cli/v3"
)

func main() {
	cmd := &cli.Command{
		Name: "semver-app",
		Flags: []cli.Flag{
			&cli.SemverFlag{
				Name:  "version",
				Value: [3]int{0, 0, 1},
				Usage: "semantic version",
			},
		},
		Action: func(ctx context.Context, c *cli.Command) error {
			v := c.Semver("version")
			fmt.Printf("Parsed version: %d.%d.%d\n", v[0], v[1], v[2])
			return nil
		},
	}

	// Test with valid inputs
	tests := [][]string{
		{"semver-app", "--version", "1.2.3"},
		{"semver-app", "--version", "v1.2.3"},
		{"semver-app", "--version", "0.10.0"},
		{"semver-app", "--version", "v0.0.0"},
	}

	for _, args := range tests {
		fmt.Printf("\n=== Testing: %v ===\n", args)
		cmd.Run(context.Background(), args)
	}

	// Test with invalid inputs
	invalidTests := [][]string{
		{"semver-app", "--version", "1.2"},
		{"semver-app", "--version", "1.2.3.4"},
		{"semver-app", "--version", "1.2.x"},
	}

	for _, args := range invalidTests {
		fmt.Printf("\n=== Testing invalid: %v ===\n", args)
		cmd.Run(context.Background(), args)
	}
}
EOF
